 ("table", ["Gas", "Share of atmosphere"], [["**Nitrogen**", "78%"], ["**Oxygen**", "21%"], ["Argon", "0.93%"], ["**Carbon dioxide**", "0.04%"], ["Others (helium, neon, krypton, xenon, ozone, hydrogen)", "0.03%"]]),
